$thickbodyC$, sections = '[{"heading": "Key facts", "summary": "- The PPWR is an EU regulation, so it applies directly in every member state without national transposition, replacing the old Packaging and Packaging Waste Directive (94/62/EC)."}, {"heading": "What the PPWR is", "summary": "The PPWR is an EU regulation, which means it applies directly in every member state without national transposition."}, {"heading": "Who it applies to", "summary": "The PPWR applies to economic operators across the packaging chain: packaging manufacturers, importers who bring packaged goods into the EU, distributors, and the producers who place packaged products on the market."}, {"heading": "Key obligations", "summary": "1."}, {"heading": "EPR in practice: registration per member state", "summary": "EPR is where the PPWR meets national administration."}, {"heading": "The phase-in timeline", "summary": "| Milestone | What happens |."}, {"heading": "Compliance checklist", "summary": "- [ ] Inventory every packaging component you place on the EU market (primary, secondary, transport), per SKU and parcel configuration."}, {"heading": "What this means for businesses", "summary": "For businesses, the PPWR turns packaging from a procurement detail into a regulated product in its own right."}, {"heading": "How the EU compares with other markets", "summary": "The EU now has a single directly applicable packaging regulation."}, {"heading": "Does the PPWR apply to packaging around imported goods?", "summary": "Yes, it covers all packaging placed on the EU market regardless of origin."}, {"heading": "Who is the \"producer\" for EPR purposes?", "summary": "Generally the company first placing the packaged product on a member state''s market; distance sellers can be caught directly."}, {"heading": "Do I need a separate EPR registration per EU country?", "summary": "Yes, registration is national."}, {"heading": "What happens to the old Packaging Directive?", "summary": "The PPWR replaces Directive 94/62/EC."}, {"heading": "What are the recyclability performance grades?", "summary": "A grading system for packaging recyclability that applies from 2030, defined in detail through delegated acts."}, {"heading": "Do beverage bottles need deposit return schemes?", "summary": "The regulation sets separate-collection objectives for single-use plastic beverage bottles and metal beverage containers, with DRS as the default mechanism targeting high collection rates by 2029."}, {"heading": "Assumptions and limitations", "summary": "- This guide summarises the framework as of the last-verified date; delegated and implementing acts continue to add detail (for example on recyclability grades and labelling formats)."}, {"heading": "Official sources", "summary": "- [Regulation (EU) 2025/40 on EUR-Lex (English)](https://eur-lex.europa.eu/eli/reg/2025/40/oj/eng)."}]'::jsonb, short_answer = 'The PPWR (Regulation (EU) 2025/40) is the EU''s single directly applicable rulebook for all packaging placed on the EU market. It sets design-for-recycling requirements with recyclability grades from 2030, substance restrictions including PFAS limits for food-contact packaging, harmonised labelling, extended producer responsibility with per-member-state registration, and declaration-of-conformity duties. It generally applies from 12 August 2026.', updated_at = now() WHERE slug = 'ppwr-packaging-obligations-eu';